#define STRICT_LIBRARY
#include "strict.cpp"
// Only KPvKP has upper bounds >12. With no captures or pawn moves, both kings must return after three moves each.
bool six(int id,Pos p){auto&t=ts[id];if(p.ep||t.v[enc(t,p)]!=0)return false;bool found=false;function<void(Pos,int)> dfs=[&](Pos x,int depth){if(found)return;if(depth==6){found=x.s[0]==p.s[0]&&x.s[1]==p.s[1];return;}moves(t,x,[&](Move m,Pos y){if(found||m.i>1||m.cap>=0||m.pr)return;if(depth>=4&&m.to!=p.s[m.i])return;y.turn=1-x.turn;y.ep=0;if(t.v[enc(t,y)]==0)dfs(y,depth+1);});};dfs(p,0);return found;}
int main(){init();setup();load();loadD();int id=ids[P][P][1];auto&t=ts[id];vector<D> v(t.sz);ifstream f("rep4_"+t.name+".bin",ios::binary);f.read((char*)v.data(),2ull*t.sz);assert(f.gcount()==2ull*t.sz);vector<vector<U>> buckets(32);auto push=[&](U a,int k){if(k<v[a]){v[a]=k;buckets[k].push_back(a);}};long long candidates=0,seeds=0;for(U a=0;a<(U)t.sz;a++)if(t.v[a]==0&&v[a]>12){candidates++;if(six(id,dec(t,a))){push(a,12);seeds++;}}for(int k=12;k<31;k++)for(U a:buckets[k]){if(v[a]!=k)continue;preds(t,dec(t,a),[&](U b){if(t.v[b]==0)push(b,k+1);});}map<int,long long> h;long long change=0;int ma=0;for(U a=0;a<(U)t.sz;a++)if(pc(t.v[a])==0){assert(v[a]<=16);h[v[a]]++;ma=max(ma,int(v[a]));if(v[a]<ds[id][a])change++;}ofstream o("rep3_"+t.name+".bin",ios::binary);o.write((char*)v.data(),2ull*v.size());ofstream hh("repeat6_hist.tsv");for(auto[k,n]:h)hh<<t.name<<'\t'<<k<<'\t'<<n<<'\n';cout<<"candidates "<<candidates<<" six seeds "<<seeds<<" improved from D0 "<<change<<" max "<<ma<<endl;}
